            let sampleAlpha = clamp(sampleFlagWithAlpha.y * 0.5, 0.01, 1.0);

            let isOpaque = sampleFlag > 0.20 && sampleFlag < 0.30;
            let isTransparent = sampleFlag > 0.45 && sampleFlag < 0.55;
            let isBoth = sampleFlag > 0.70 && sampleFlag < 0.80;

